CREATE TABLE IF NOT EXISTS project_staging_vault_v1 (project_id TEXT PRIMARY KEY REFERENCES zones_registry(project_id),vault_kind TEXT NOT NULL DEFAULT 'logical_prelaunch',visibility TEXT NOT NULL DEFAULT 'HOLD',domain_name TEXT,cloudflare_zone_id TEXT,launch_approved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_staging_components_v1 (project_id TEXT NOT NULL REFERENCES zones_registry(project_id),component_kind TEXT NOT NULL,component_key TEXT NOT NULL,source_reference TEXT,readiness TEXT NOT NULL DEFAULT 'catalogued',PRIMARY KEY(project_id,component_kind,component_key));
INSERT OR IGNORE INTO project_staging_vault_v1(project_id,domain_name,cloudflare_zone_id) SELECT project_id,domain_name,zone_id FROM zones_registry;
INSERT OR IGNORE INTO project_staging_components_v1(project_id,component_kind,component_key,source_reference) SELECT project_id,'staging_endpoint','primary',staging_url FROM zones_registry WHERE staging_url IS NOT NULL;
INSERT OR IGNORE INTO project_staging_components_v1(project_id,component_kind,component_key,source_reference) SELECT z.project_id,'existing_worker',a.worker_name,a.public_url FROM zones_registry z JOIN virtual_app_v1 a ON z.project_id=a.app_id;
